/// <summary>
///     Extension class for DlvTerm
/// </summary>
[ExtensionOf(tableStr(DlvTerm))]
final class AVADlvTermTbl_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>avaTxtOrId</c> method.
/// </summary>
/// <param name="_id">
///     <c>DlvTermId</c> as type
/// </param>
/// <param name="_languageId">
///     <c>LanguageId</c> as type
/// </param>
/// <returns>
///    <c>FreeText</c> as return value
/// </returns>
public static FreeText avaTxtOrId(  DlvTermId   _id,
                                    LanguageId  _languageId = CompanyInfo::languageId() )
{
    FreeText retVal;

    if(_id && DlvTerm::exist(_id))
    {
        //@SYS6576
        retVal      = DlvTerm::txt( _id, 
                                    _languageId );
        if(!retVal)
        {
            retVal  = _id;
        }
    }
    return retVal;
}
